from django.db import migrations


def backfill_step_order(apps, schema_editor):
    """按每个 Action 内 step 的现有 id 顺序回填 order（1、2、3…）"""
    Step = apps.get_model("case_ui", "Step")
    updated = 0
    action_ids = (
        Step.objects.order_by("action_id_id")
        .values_list("action_id_id", flat=True)
        .distinct()
    )
    for action_id in action_ids:
        steps = list(Step.objects.filter(action_id_id=action_id).order_by("id"))
        for i, s in enumerate(steps, 1):
            if s.order != i:
                s.order = i
                s.save(update_fields=["order"])
                updated += 1
    print(f"backfilled {updated} step(s)")


def noop(apps, schema_editor):
    pass


